/** The resource dimensions every plan caps. Adding a field here ripples into
 *  `PLAN_LIMITS`, `BillingService`, the usage UI and the limit guards. */
export type LimitedResource =
  | "seats"
  | "projects"
  | "issuesPerProject"
  | "storageMb"
  | "apiRequestsPerHour"
  | "webhooks";

/** Result of a single quota check, returned by `BillingService.checkLimit`. */
export interface LimitCheck {
  readonly resource: LimitedResource;
  readonly plan: PlanId;
  readonly limit: number;
  readonly used: number;
----
import type {
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
----
  storageMb: "Storage (MB)",
  apiRequestsPerHour: "API requests / hour",
  webhooks: "Webhooks",
};

const RESOURCE_ORDER: readonly LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
----
): Promise<void> {
  const usage = await getUsage(actor, input.orgId);
  const limits = getPlanLimits(input.plan);

  const consumption: ReadonlyArray<readonly [LimitedResource, number]> = [
    ["seats", usage.seatsUsed],
    ["projects", usage.projectsUsed],
    ["storageMb", usage.storageMbUsed],
  ];

